(2221230, 304210, 52731, '<td valign="top">I really like the Depth of field you used. It adds to this a lot.</td>', 'I really like the Depth of field you used. It adds to this a lot.', '2006-03-12 09:43:08.000000', NULL, 1),
(2221235, 303937, 52731, '<td valign="top">I think this quite misses the whole challenge topic. seems intended just to gross people out and make them react badly.</td>', 'I think this quite misses the whole challenge topic. seems intended just to gross people out and make them react badly.', '2006-03-12 09:44:49.000000', NULL, 1),
