(2221244, 304108, 52731, '<td valign="top">Too obvious a choice.</td>', 'Too obvious a choice.', '2006-03-12 09:46:26.000000', NULL, 1),
(2221249, 303444, 52731, '<td valign="top">Seems like there''s just too much here to look at, it might''ve worked better cropped around the bell and/or cross. Maybe a different angle too.</td>', 'Seems like there''s just too much here to look at, it might''ve worked better cropped around the bell and/or cross. Maybe a different angle too.', '2006-03-12 09:48:00.000000', NULL, 1),
(2221251, 303263, 52731, '<td valign="top">I don''t see how this really has to do with the afterlife, besides that it''s taken after this animal''s life. Good shot though, focus and angle are good.</td>', 'I don''t see how this really has to do with the afterlife, besides that it''s taken after this animal''s life. Good shot though, focus and angle are good.', '2006-03-12 09:48:57.000000', NULL, 1),
