(2225465, 303709, 53572, '<td valign="top">pretty impressive for basic.  but, it just kinda leaves me cold.  hah, no pun intended!</td>', 'pretty impressive for basic.  but, it just kinda leaves me cold.  hah, no pun intended!', '2006-03-13 19:20:34.000000', NULL, 1),
