(2225777, 302318, 42013, '<td valign="top">Dueling images competing for a ribbon, will it be white or black which wins.  Good luck. :)  10 for bravery, 1 for effort.  NOt sure where to place this one :)</td>', 'Dueling images competing for a ribbon, will it be white or black which wins.  Good luck. :)  10 for bravery, 1 for effort.  NOt sure where to place this one :)', '2006-03-13 21:33:14.000000', NULL, 1),
(2225782, 304147, 42013, '<td valign="top">I need some tips from you regarding photographing smoke.  Good job and good luck.</td>', 'I need some tips from you regarding photographing smoke.  Good job and good luck.', '2006-03-13 21:35:05.000000', NULL, 1),
(2225785, 303953, 42013, '<td valign="top">I''m sorry for your loss.</td>', 'I''m sorry for your loss.', '2006-03-13 21:37:51.000000', NULL, 1),
